// Flatten all questions with category assigned
export const ALL_QUESTIONS: Question[] = Object.entries(RAW_QUESTIONS).flatMap(
  ([catKey, items]) =>
    items.map((item, index) => ({
      ...item,
      cat: catKey as CategoryKey,
      id: `${catKey}-${index + 1}`,
    }))
);
